print("Test target distribution  (Class 1):", np.mean(y_test)) # Added print


############################################################
# 7) 데이터 정규화 (변경 없음 - 시계열 데이터에 동일하게 적용)
############################################################
# NaN/Inf check before reshape/scaling (minimal handling) - Already done before loop
