# Check for necessary columns before creating features
required_cols_fin = ['STCK_PRPR', 'W52_HGPR', 'W52_LWPR', 'NET_INCOME', 'MARKET_CAP', 'PS', 'NET_DEBT', 'DEBT_COST', 'SCRT_GRP_CLS_CODE', 'MRKT_DIV_CLS_CODE']
