if 'SCRT_GRP_CLS_CODE' in fin_df.columns:
    fin_df['SCRT_GRP_CLS_CODE'] = fin_df['SCRT_GRP_CLS_CODE'].astype(str)
    fin_df['SCRT_GRP_CLS_CODE'] = le_scrt.fit_transform(fin_df['SCRT_GRP_CLS_CODE'])
