test_mask  = dates >= pd.Timestamp('2023-01-01')
if not np.any(train_mask) or not np.any(test_mask): raise ValueError(f"Data splitting error: Train samples={np.sum(train_mask)}, Test samples={np.sum(test_mask)}.")
