# (2016, 2020, 2021, [2022]),  # Train: 2016~2018, Val: 2019, Test: 2021
# (2017, 2021, 2022, [2023]),  # Train: 2016~2018, Val: 2019, Test: 2021
# (2018, 2022, 2023, [2024]),  # Train: 2016~2018, Val: 2019, Test: 2021
